select distinct on (game_id,market,period,statistic,player_id,case when market='spread' and side='away' then -line else line end) game_id::text as "gameId",market,period,statistic,player_id::text as "playerId",line::float,side,decision_at as "decisionAt",inserted_at as "recordedAt",game_start_at as "scheduledAt",model_version as model,forecast_id as id from nba_decision_shadow_forecasts_v1 where decision_at<game_start_at and inserted_at<game_start_at and quote_captured_at<=decision_at and market in ('moneyline','spread','total','props') and model_version='NBA_DECISION_BOARD_SHADOW_V1' order by game_id,market,period,statistic,player_id,case when market='spread' and side='away' then -line else line end,decision_at,inserted_at,forecast_id
